#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char **argv) {
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }
    const char *s1 = argv[1];
    const char *s2 = argv[2];
    /* Length limit: 1024 characters (as observed in the original binary) */
    if (strlen(s1) >= 1024 || strlen(s2) >= 1024) {
        puts("TOO_LONG");
        return 0;
    }
    int freq[256] = {0};
    for (size_t i = 0; s1[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s1[i];
        if (c == ' ') continue;               // ignore spaces
        if (isalpha(c)) c = (unsigned char)tolower(c);
        freq[c]++;
    }
    for (size_t i = 0; s2[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s2[i];
        if (c == ' ') continue;               // ignore spaces
        if (isalpha(c)) c = (unsigned char)tolower(c);
        freq[c]--;
    }
    for (int i = 0; i < 256; ++i) {
        if (freq[i] != 0) {
            puts("NOT_ANAGRAM");
            return 0;
        }
    }
    puts("ANAGRAM");
    return 0;
}
